#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals seqmatrix. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Definition point := R * R * R. Variables A B C D : point. Variable s : R. Hypothesis hs : s > 0. Definition plane_P (p : point) := let '(_, _, z) := p in z = 0. Hypothesis hA : let '(_, _, zA) := A in zA = 0. Hypothesis hB : let '(_, _, zB) := B in zB = 2. Hypothesis hC : let '(_, _, zC) := C in zC = 8. Hypothesis hD : let '(_, _, zD) := D in zD = 6. Theorem height_difference_faces : exists avg_z : R, 0 <= avg_z <= s. Proof. Admitted.
